import { PageHero } from "../components/PageBits";
import { hsePage } from "../content";
import { Link } from "../router";

/**
 * Downloads. The documents are real PDFs in `public/downloads/`, generated by
 * the branded template in `_verify/make-pdfs.mjs` — see that file to regenerate
 * after a copy or branding change.
 */
const DOCS = {
  "capability-statement": {
    slug: "capability-statement",
    title: "Capability Statement",
    file: "corvex-capability-statement.pdf",
    pages: 3,
    desc: "Company overview, service lines, sectors served, delivery method, standards applied, and contact routes.",
  },
  "hse-policy": {
    slug: "hse-policy",
    title: "HSE Policy",
    file: "corvex-hse-policy.pdf",
    pages: 3,
    desc: "Corporate policy statement, health and safety commitments, environmental protection, hazard management, incident reporting and continuous improvement.",
  },
  "quality-policy": {
    slug: "quality-policy",
    title: "Quality Policy",
    file: "corvex-quality-policy.pdf",
    pages: 2,
    desc: "QA/QC framework, inspection and test plan governance, material and weld traceability, and non-conformance management.",
  },
};

const ORDER = ["hse-policy", "capability-statement", "quality-policy"];

export default function DownloadPage({ slug }) {
  const d = DOCS[slug] ?? DOCS["capability-statement"];
  const others = ORDER.filter((s) => s !== d.slug).map((s) => DOCS[s]);

  return (
    <>
      <PageHero
        index="Downloads"
        title={d.title}
        intro={d.desc}
        breadcrumb={[{ label: "Resources" }, { label: d.title }]}
      />
      <section className="section" style={{ background: "#fff", color: "#000" }}>
        <div className="wrap" style={{ maxWidth: 820, marginInline: "auto" }}>
          <div
            style={{
              border: "1px solid rgba(0,0,0,.15)",
              padding: 32,
              display: "flex",
              gap: 24,
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            <span
              aria-hidden="true"
              style={{
                fontFamily: "var(--font-display)",
                fontSize: 12,
                letterSpacing: ".1em",
                border: "1px solid rgba(0,0,0,.3)",
                padding: "10px 12px",
              }}
            >
              PDF
            </span>
            <span style={{ flex: 1, minWidth: 220 }}>
              <p style={{ fontWeight: 600, fontSize: 17 }}>{d.title}</p>
              <p className="caption" style={{ color: "var(--color-ash)", marginTop: 4 }}>
                {d.pages} pages · {d.file}
              </p>
            </span>
            <a
              href={`/downloads/${d.file}`}
              download
              className="btn btn-primary chamfer-tr-sm"
              style={{ textDecoration: "none" }}
            >
              Download PDF
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                <path d="M8 2v8m0 0 3-3m-3 3L5 7M2 13h12" stroke="currentColor" strokeWidth="1.6" strokeLinecap="square" />
              </svg>
            </a>
          </div>

          <p className="body" style={{ color: "var(--color-body-light)", marginTop: 24 }}>
            Opens and downloads as a PDF. These documents are issued for the demonstration
            build — see the notice on the final page of each file.
          </p>

          <h2 className="h3" style={{ marginTop: 48 }}>Other documents</h2>
          <ul style={{ listStyle: "none", margin: "16px 0 0", padding: 0 }}>
            {others.map((o) => (
              <li key={o.slug} style={{ borderTop: "1px solid rgba(0,0,0,.15)" }}>
                <Link
                  to={`/downloads/${o.slug}`}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    gap: 16,
                    padding: "18px 0",
                    textDecoration: "none",
                    color: "inherit",
                  }}
                >
                  <span>
                    <span style={{ display: "block", fontWeight: 600, fontSize: 16 }}>{o.title}</span>
                    <span className="body" style={{ display: "block", color: "var(--color-body-light)", marginTop: 2 }}>
                      {o.pages} pages · PDF
                    </span>
                  </span>
                  <span style={{ color: "var(--color-signal)", fontFamily: "var(--font-display)", fontSize: 13 }}>→</span>
                </Link>
              </li>
            ))}
            <li style={{ borderTop: "1px solid rgba(0,0,0,.15)", borderBottom: "1px solid rgba(0,0,0,.15)" }} />
          </ul>

          <div style={{ marginTop: 48, background: "#f4f4f3", padding: 24, borderLeft: "3px solid var(--color-signal)" }}>
            <p style={{ fontWeight: 600 }}>Need something specific?</p>
            <p className="body" style={{ color: "var(--color-body-light)", marginTop: 6 }}>
              Certificates, insurance documentation and contract-specific references are issued on request.
            </p>
            <Link to="/contact" className="text-link body" style={{ color: "var(--color-signal)", marginTop: 12, display: "inline-flex" }}>
              Request documentation →
            </Link>
          </div>
        </div>
      </section>
    </>
  );
}

/** Index of every downloadable document, for the safety page and footer. */
export const documentIndex = ORDER.map((s) => DOCS[s]);

export const hseDownloads = hsePage.downloads;
